338:   #[napi]
339:   pub fn to_blob(
340:     &mut self,
341:     env: &Env,
342:     callback: Function<Either<Uint8ArraySlice, Null>, Unknown>,
343:     mime: Option<String>,
344:     quality: Option<f64>,
345:   ) -> Result<()> {
346:     // Flush deferred rendering before encoding
347:     self.ctx.context.flush();
348:     let surface_data = self.ctx.context.surface.reference();
349:     let mime = mime.unwrap_or_else(|| MIME_PNG.to_owned());
350:     let quality_value = quality.unwrap_or(0.92).clamp(0.0, 1.0);
351:     let quality_or_config = if mime == MIME_AVIF {
352:       Either::B(AvifConfig {
353:         quality: Some((quality_value * 100.0) as u32),
354:         ..Default::default()
355:       })
356:     } else {
357:       Either::A((quality_value * 100.0) as u32)
358:     };
359:     let width = self.ctx.context.width;
360:     let height = self.ctx.context.height;
361:     let callback_ref = Rc::new(callback.create_ref()?);
362:     let callback_ref_in_catch = callback_ref.clone();
363:     let async_blob_task = AsyncBlob {
364:       surface_ref: surface_data,
365:       mime,
366:       quality_or_config,
367:       width,
368:       height,
369:     };
370: 
371:     env
372:       .spawn(async_blob_task)?
373:       .promise_object()
374:       .then(move |ctx| {
375:         let callback = callback_ref.borrow_back(&ctx.env)?;
376:         callback.call(Either::A(ctx.value))?;
377:         Ok(())
378:       })?
379:       .catch(|ctx: CallbackContext<Unknown>| {
380:         let callback = callback_ref_in_catch.borrow_back(&ctx.env)?;
381:         callback.call(Either::B(Null))?;
382:         Ok(())
383:       })?;
384: 
385:     Ok(())
386:   }
