471:   fn encode_inner(
472:     &self,
473:     format: String,
474:     quality_or_config: Either3<u32, AvifConfig, Unknown>,
475:   ) -> Result<ContextData> {
476:     let format_str = format.as_str();
477:     let quality = match &quality_or_config {
478:       Either3::A(q) => (*q) as u8,
479:       Either3::B(s) => s.quality.map(|q| q as u8).unwrap_or(DEFAULT_JPEG_QUALITY),
480:       Either3::C(_) => DEFAULT_JPEG_QUALITY,
481:     };
482:     let ctx2d = &self.ctx.context;
483:     let surface_ref = ctx2d.surface.reference();
484: 
485:     let task = match format_str {
486:       "webp" => ContextData::Webp(surface_ref, quality),
487:       "jpeg" => ContextData::Jpeg(surface_ref, quality),
488:       "png" => ContextData::Png(surface_ref),
489:       "avif" => {
490:         let cfg = AvifConfig::from(&quality_or_config);
491:         ContextData::Avif(surface_ref, cfg.into(), ctx2d.width, ctx2d.height)
492:       }
493:       "gif" => {
494:         let cfg = gif::GifConfig {
495:           quality: match &quality_or_config {
496:             Either3::A(q) => Some(*q),
497:             _ => None,
498:           },
499:         };
500:         ContextData::Gif(surface_ref, cfg, ctx2d.width, ctx2d.height)
501:       }
502:       _ => {
503:         return Err(Error::new(
504:           Status::InvalidArg,
505:           format!("{format_str} is not valid format"),
506:         ));
507:       }
508:     };
509: 
510:     Ok(task)
511:   }
