538: fn get_data_ref(
539:   surface_ref: &SurfaceRef,
540:   mime: &str,
541:   quality_or_config: &Either<u32, AvifConfig>,
542:   width: u32,
543:   height: u32,
544: ) -> Result<ContextOutputData> {
545:   let quality = quality_or_config.to_quality(mime);
546: 
547:   if let Some(data_ref) = match mime {
548:     MIME_WEBP => surface_ref.encode_data(sk::SkEncodedImageFormat::Webp, quality),
549:     MIME_JPEG => surface_ref.encode_data(sk::SkEncodedImageFormat::Jpeg, quality),
550:     MIME_PNG => surface_ref.png_data(),
551:     MIME_AVIF => {
552:       let (data, size) = surface_ref.data().ok_or_else(|| {
553:         Error::new(
554:           Status::GenericFailure,
555:           "Encode to avif error, failed to get surface pixels".to_owned(),
556:         )
557:       })?;
558:       let config = AvifConfig::from(quality_or_config).into();
559:       let output = avif::encode(
560:         unsafe { slice::from_raw_parts(data, size) },
561:         width,
562:         height,
563:         &config,
564:       )
565:       .map_err(|e| Error::new(Status::GenericFailure, format!("{e}")))?;
566:       return Ok(ContextOutputData::Avif(output));
567:     }
568:     MIME_GIF => {
569:       let config = gif::GifConfig {
570:         quality: match quality_or_config {
571:           Either::A(q) => Some(*q),
572:           _ => None,
573:         },
574:       };
575:       let output = gif::encode_surface(surface_ref, width, height, &config)
576:         .map_err(|e| Error::new(Status::GenericFailure, format!("{e}")))?;
577:       return Ok(ContextOutputData::Gif(output));
578:     }
579:     _ => {
580:       return Err(Error::new(
581:         Status::InvalidArg,
582:         format!("{mime} is not valid mime"),
583:       ));
584:     }
585:   } {
586:     Ok(ContextOutputData::Skia(data_ref))
587:   } else {
588:     Err(Error::new(
589:       Status::InvalidArg,
590:       format!("encode {mime} output failed"),
591:     ))
592:   }
593: }
