48: impl Font {
49:   pub fn new(font_rules: &str) -> Result<Font, SkError> {
50:     let font_regexp = FONT_REGEXP.get_or_init(init_font_regexp);
51:     let default_font = Font::default();
52:     if let Some(cap) = font_regexp.captures(font_rules) {
53:       let size_str = cap.get(7).or_else(|| cap.get(5)).unwrap().as_str();
54:       let size = if size_str.ends_with('%') {
55:         size_str
56:           .parse::<f32>()
57:           .map(|v| v / 100.0 * FONT_MEDIUM_PX)
58:           .ok()
59:       } else {
60:         size_str.parse::<f32>().ok()
61:       };
62:       let family = cap.get(11).map(|c| c.as_str()).unwrap_or(DEFAULT_FONT);
63:       // return if no valid size
64:       if let Some(size) = size {
65:         let style = cap
66:           .get(2)
67:           .and_then(|m| FontStyle::from_str(m.as_str()).ok())
68:           .unwrap_or(default_font.style);
69:         let variant = cap
70:           .get(3)
71:           .and_then(|m| FontVariant::from_str(m.as_str()).ok())
72:           .unwrap_or(default_font.variant);
73:         let weight = cap
74:           .get(4)
75:           .and_then(|m| parse_font_weight(m.as_str()))
76:           .unwrap_or(default_font.weight);
77:         // treat stretch as size
78:         // the `20%` of '20% Arial' is treated as `stretch` but it's size actually
79:         let stretch = if cap.get(6).is_none() {
80:           default_font.stretch
81:         } else {
82:           cap
83:             .get(5)
84:             .and_then(|m| parse_font_stretch(m.as_str()))
85:             .unwrap_or(default_font.stretch)
86:         };
87:         let size_px = parse_size_px(size, cap.get(8).map(|m| m.as_str()).unwrap_or("px"));
88:         Ok(Font {
89:           style,
90:           variant,
91:           weight,
92:           size: size_px,
93:           stretch,
94:           family: family
95:             .split(',')
96:             .map(|string| string.trim())
97:             .map(|s| {
98:               if s.starts_with('"') || s.starts_with('\'') {
99:                 unsafe { s.get_unchecked(1..s.len() - 1) }
100:               } else {
101:                 s
102:               }
103:             })
104:             .collect::<Vec<&str>>()
105:             .join(","),
106:         })
107:       } else {
108:         Err(SkError::InvalidFontStyle(font_rules.to_owned()))
109:       }
110:     } else {
111:       Err(SkError::InvalidFontStyle(font_rules.to_owned()))
112:     }
113:   }
114: }
