122:       (small-caps|normal){0,1}\s+                  |  # variant
123:       (bold|bolder|lighter|[1-9]00|normal){0,1}\s+ |  # weight
124:       (ultra-condensed|extra-condensed|condensed|semi-condensed|semi-expanded|expanded|extra-expanded|ultra-expanded|[\d\.]+%){0,1}\s+ # stretch
