250: // https://drafts.csswg.org/css-fonts-4/#propdef-font-weight
251: fn parse_font_weight(weight: &str) -> Option<u32> {
252:   match weight {
253:     "lighter" | "100" => Some(100),
254:     "200" => Some(200),
255:     "300" => Some(300),
256:     "normal" | "400" => Some(400),
257:     "500" => Some(500),
258:     "600" => Some(600),
259:     "bold" | "bolder" | "700" => Some(700),
260:     _ => weight.parse::<f32>().ok().and_then(|w| {
261:       if (MIN_FONT_WEIGHT..=MAX_FONT_WEIGHT).contains(&w) {
262:         Some(w as u32)
263:       } else {
264:         None
265:       }
266:     }),
267:   }
268: }
