270: pub fn parse_font_stretch(stretch: &str) -> Option<FontStretch> {
271:   match stretch {
272:     "ultra-condensed" | "50%" => Some(FontStretch::UltraCondensed),
273:     "extra-condensed" | "62.5%" => Some(FontStretch::ExtraCondensed),
274:     "condensed" | "75%" => Some(FontStretch::Condensed),
275:     "semi-condensed" | "87.5%" => Some(FontStretch::SemiCondensed),
276:     "normal" | "100%" => Some(FontStretch::Normal),
277:     "semi-expanded" | "112.5%" => Some(FontStretch::SemiExpanded),
278:     "expanded" | "125%" => Some(FontStretch::Expanded),
279:     "extra-expanded" | "150%" => Some(FontStretch::ExtraExpanded),
280:     "ultra-expanded" | "200%" => Some(FontStretch::UltraExpanded),
281:     _ => None,
282:   }
283: }
