285: pub fn parse_size_px(size: f32, unit: &str) -> f32 {
286:   let mut size_px = size;
287:   match unit {
288:     "em" | "rem" | "pc" => {
289:       size_px = size * FONT_MEDIUM_PX;
290:     }
291:     "pt" => {
292:       size_px = size * 4.0 / 3.0;
293:     }
294:     "px" => {
295:       size_px = size;
296:     }
297:     "in" => {
298:       size_px = size * 96.0;
299:     }
300:     "cm" => {
301:       size_px = size * 96.0 / 2.54;
302:     }
303:     "mm" => {
304:       size_px = size * 96.0 / 25.4;
305:     }
306:     "q" => {
307:       size_px = size * 96.0 / 25.4 / 4.0;
308:     }
309:     "%" => {
310:       size_px = size * FONT_MEDIUM_PX / 100.0;
311:     }
312:     _ => {}
313:   };
314:   size_px
315: }
